import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第八十七章 痛苦如同芦苇互相支撑直立","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/87第八十七章 痛苦如同芦苇互相支撑直立.md","filePath":"meditation/巴利文大藏经/87第八十七章 痛苦如同芦苇互相支撑直立.md"}'),o={name:"meditation/巴利文大藏经/87第八十七章 痛苦如同芦苇互相支撑直立.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第八十七章-痛苦如同芦苇互相支撑直立" tabindex="-1">第八十七章 痛苦如同芦苇互相支撑直立 <a class="header-anchor" href="#第八十七章-痛苦如同芦苇互相支撑直立" aria-label="Permalink to &quot;第八十七章 痛苦如同芦苇互相支撑直立&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部12相应67经/芦苇束经(因缘相应/因缘篇/修多罗)</p><p>有个时候，舍利弗尊者与摩诃拘絺罗尊者住在波罗奈的鹿野苑，有一天傍晚，摩诃拘絺罗尊者静坐完毕后，来到舍利弗尊者的住处，他与舍利弗尊者互相问候后，就在一旁坐下，摩诃拘絺罗尊者对舍利弗尊者说：“舍利弗学友，「老死」是自己造作出来的吗？「老死」是其他人或是其他事物造作出来的吗？「老死」是自己和其他人或事物共同造作出来的吗？「老死」既不是自己，也不是其他人或事物造作出来的吗？「老死」是没有原由，没有前因偶然产生出来的吗？”</p><p>舍利弗尊者回答：“拘絺罗学友，「老死」不是自己造作出来的；「老死」不是其他人或其他事物造作出来的；「老死」也不是自己和其他人或事物共同造作出来的；当然认为「老死」既不是自己造作出来的，也不是其他人或事物造作出来的见解也不正确；「老死」更不是没有原由，没有前因偶然产生出来的。拘絺罗学友，以「生」为前提条件就会有「老死」的产生。这就是缘起法（缘起法解释，见第四十八章、第四十九章）。”</p><p>摩诃拘絺罗尊者继续问舍利弗尊者：“舍利弗学友，「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」是自己造作出来的吗？「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」是其他人或是其他事物造作出来的吗？「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」是自己和其他人或事物共同造作出来的吗？「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」既不是自己，也不是其他人或事物造作出来的吗？「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」是没有原由，没有前因偶然产生出来的吗？”</p><p>舍利弗尊者回答：“拘絺罗学友，「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」不是自己造作出来的；「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」不是其他人或其他事物造作出来的；「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」也不是自己和其他人或事物共同造作出来的；当然认为「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」既不是自己造作出来的，也不是其他人或事物造作出来的见解也不正确；「生」、「有」、「取」、「爱」、「受」、「触」、「六处」、「名色」、「识」、「行」、「无明」更不是没有原由，没有前因偶然产生出来的。拘絺罗学友，以「无明」为前提条件产生出「行」，以「行」为前提条件产生出「识」，以「识」为前提条件产生出「名色」，以「名色」为前提条件产生出「六处」，以「六处」为前提条件产生出「触」，以「触」为前提条件产生出「受」，以「受」为前提条件产生出「爱」，以「爱」为前提条件产生出「取」，以「取」为前提条件产生出「有」，以「有」为前提条件产生出「生」，这样有「生」就会产生出忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。这就是世间人或众生痛苦和烦恼聚集、出现的过程，世间的人或众生按缘起法（缘起法解释，见第四十八章、第四十九章）的顺行就会继续的在生死轮回中煎熬沉沦，受尽折磨和痛苦。”</p><p>摩诃拘絺罗尊者说：“舍利弗学友，您能简单的做个比喻吗？您这样说法，我感觉有点难以理解。”</p><p>舍利弗尊者说：“拘絺罗学友，那我就用一个比喻来说明缘起法的义理，拘絺罗学友，就如同将两束芦苇互相依靠着放置在一起，这两束芦苇能够互相支撑着直立起来，同样的道理，「无明」、「行」、「识」、「名色」、「六处」、「触」、「受」、「爱」、「取」、「有」、「生」、「老死」也是互相依靠，互相支撑，互为前提条件才能产生出来的。也就是：以「无明」为前提条件产生出「行」，以「行」为前提条件产生出「识」，以「识」为前提条件产生出「名色」，以「名色」为前提条件产生出「六处」，以「六处」为前提条件产生出「触」，以「触」为前提条件产生出「受」，以「受」为前提条件产生出「爱」，以「爱」为前提条件产生出「取」，以「取」为前提条件产生出「有」，以「有」为前提条件产生出「生」，这样有「生」就会产生出忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。”</p><p>拘絺罗学友，如果把这两束芦苇中的其中一个拿开，那么另一束芦苇就会倒下，就无法继续的互相支撑保持直立。也就是说不管拿开那一束芦苇剩下的那一束芦苇就会倒下。同样的道理，「无明」、「行」、「识」、「名色」、「六处」、「触」、「受」、「爱」、「取」、「有」、「生」、「老死」其中的哪一个被灭尽了，那么由这个为前提条件产生出来的因缘就灭尽了。简单的说就是：这个灭尽了，则那个也会灭尽；这个不存在了，那个也会消失不见。也就是：「无明」完全褪去、消除、灭尽的时候，「行」就灭除了。「行」灭尽了，「识」就灭除了。「识」灭尽了，「名色」就灭除了。「名色」灭尽了，「六处」就灭除了。「六处」灭尽了，「触」就灭除了。「触」灭尽了，「受」就灭除了。「受」灭尽了，「爱」就灭除了。「爱」灭尽了，「取」就灭除了。「取」灭尽了，「有」就灭除了。「有」灭尽了，「生」就灭除了。「生」灭尽了，忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡就灭除了。这就是世间人或众生痛苦和烦恼灭除、灭尽的过程。世间的人或众生按缘起法（缘起法解释，见第四十八章、第四十九章）的逆行就能从生死轮回的烦恼和痛苦中解脱出来。”</p><p>摩诃拘絺罗尊者说：“舍利弗学友，您说的太好了，您刚才说的比喻恰到好处，我已经完全理解了您所说的法义。”</p><p>舍利弗尊者继续说：“拘絺罗学友，如果有人讲述褪去、灭尽「无明」、「行」、「识」、「名色」、「六处」、「触」、「受」、「爱」、「取」、「有」、「生」、「老死」的修行方法，讲述不执着和挂念「无明」、「行」、「识」、「名色」、「六处」、「触」、「受」、「爱」、「取」、「有」、「生」、「老死」的修行方法，那么这个说法的人，他就是讲解如来正法的法师。</p><p>拘絺罗学友，如果有个人，他为了褪去、灭尽「无明」、「行」、「识」、「名色」、「六处」、「触」、「受」、「爱」、「取」、「有」、「生」、「老死」而去修行，为了不执着和挂念「无明」、「行」、「识」、「名色」、「六处」、「触」、「受」、「爱」、「取」、「有」、「生」、「老死」而去修行。那么这个人就是按如来正法去修行的人，这个人就是依法修行的人。</p><p>拘絺罗学友，如果有个人他已经褪去、灭尽「无明」、「行」、「识」、「名色」、「六处」、「触」、「受」、「爱」、「取」、「有」、「生」、「老死」，已经不再挂念和执着「无明」、「行」、「识」、「名色」、「六处」、「触」、「受」、「爱」、「取」、「有」、「生」、「老死」，他由此从一切的烦恼和痛苦中解脱出来，那么这个人就在此刻进入了涅槃，这个人就是达到涅槃境界的人。”</p><p>舍利弗尊者说法后，摩诃拘絺罗尊者随喜赞叹舍利弗尊者说法的无量功德，并按着舍利弗尊者所说的法去修行。</p>',15)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
